{"claims":[{"claim_text":"Republicans will insist on the appointment of constitutionalist judges who will not distort founding documents to deny the people's right to self-government, sanction federal powers that violate liberties, or inject foreign law into American jurisprudence.", "claim_types":["policy_position"],"evidence_ids":[1]},{"claim_text":"Republicans oppose stealth nominations to the federal bench and especially to the Supreme Court when nominees lack a clear and distinguished record demonstrating respect for the Constitution or intellectual fortitude.", "claim_types":["policy_position"],"evidence_ids":[2]},{"claim_text":"Nominees to the federal bench must have a record of fidelity to the U.S. Constitution and the rule of law.", "claim_types":["policy_position"],"evidence_ids":[2]},{"claim_text":"Republicans reject the view that judicial nominees should guarantee particular results before a case is filed.", "claim_types":["policy_position"],"evidence_ids":[3]},{"claim_text":"Judges nominated by a Republican president will be thoughtful and open-minded and prepared to view past error in light of stare decisis, including judicial fiats that disenfranchised the American people.", "claim_types":["policy_position"],"evidence_ids":[3]},{"claim_text":"No qualified person should be denied the opportunity to serve on the federal bench due to race, ethnicity, religion or sex.", "claim_types":["policy_position"],"evidence_ids":[4]},{"claim_text":"The Senate should not inquire into a nominee's religious convictions.", "claim_types":["policy_position"],"evidence_ids":[4]},{"claim_text":"Opposition to recent judicial nominees because of their ethnicity or religion is condemned.", "claim_types":["policy_position"],"evidence_ids":[4]}],"unresolved_references":[]}
